/** Raw create-user request body as received from the network. */
export interface CreateUserInput {
  email?: unknown;
  name?: unknown;
  age?: unknown;
}

/** Create-user request after validation and normalization. */
export interface CreateUser {
  email: string;
  name: string;
  age?: number;
}

/** Outcome of {@link validateCreateUser}. */
export interface ValidationResult {
  ok: boolean;
  errors: string[];
}

/** Outcome of {@link parseCreateUser}: normalized input or the collected errors. */
export type ParseCreateUserResult =
  | { ok: true; value: CreateUser }
  | { ok: false; errors: string[] };

/** Reported when `email` is absent, not a string, or not a `local@domain.tld` address. */
export const MESSAGE_EMAIL_INVALID = "email must be a valid address";

/** Reported when `name` is absent, not a string, or blank after trimming. */
export const MESSAGE_NAME_REQUIRED = "name is required";

/** Reported when `age` is present and not a non-negative integer. */
export const MESSAGE_AGE_INVALID = "age must be a non-negative integer";

/** Reported when the request body is not a JSON object. */
export const MESSAGE_BODY_NOT_OBJECT = "request body must be a JSON object";

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Validates and normalizes a create-user request body.
 *
 * @param input - Untrusted request data, typically a decoded JSON body.
 * @returns The normalized user when every field is valid, otherwise all validation errors in field order.
 * @remarks `age` is optional; when supplied it must be a non-negative integer. String and empty values are rejected rather than coerced.
 */
export function parseCreateUser(input: unknown): ParseCreateUserResult {
  if (!isRecord(input)) {
    return { ok: false, errors: [MESSAGE_BODY_NOT_OBJECT] };
  }

  const email = typeof input.email === "string" ? input.email.trim() : "";
  const name = typeof input.name === "string" ? input.name.trim() : "";
  const rawAge = input.age;

  const errors: string[] = [];
  if (!EMAIL_PATTERN.test(email)) {
    errors.push(MESSAGE_EMAIL_INVALID);
  }
  if (name.length === 0) {
    errors.push(MESSAGE_NAME_REQUIRED);
  }
  const hasValidAge =
    rawAge === undefined ||
    (typeof rawAge === "number" && Number.isInteger(rawAge) && rawAge >= 0);
  if (!hasValidAge) {
    errors.push(MESSAGE_AGE_INVALID);
  }

  if (errors.length > 0) {
    return { ok: false, errors };
  }

  return {
    ok: true,
    value: typeof rawAge === "number" ? { email, name, age: rawAge } : { email, name },
  };
}

/**
 * Validates a create-user request at the API boundary.
 *
 * @param input - Untrusted request data.
 * @returns Whether the input is valid and the list of validation errors.
 */
export function validateCreateUser(input: unknown): ValidationResult {
  const parsed = parseCreateUser(input);
  return parsed.ok ? { ok: true, errors: [] } : { ok: false, errors: parsed.errors };
}
